// TRACE_SYSTEM skb
// The C header guard and TRACE_HEADER_MULTI_READ condition are intentionally
// preserved as source-level conditional intent.

// Dependencies supplied by the surrounding kernel translation:
// linux/skbuff.h, linux/netdevice.h, linux/tracepoint.h, and
// trace/define_trace.h.

// TRACE_DEFINE_ENUM(SKB_DROP_REASON_##reason) and DEFINE_DROP_REASON(FN, FN)
// expand to the kernel's skb_drop_reason trace enumeration declarations.
// The FN/FNe mappings used by the symbolic printer are likewise generated by
// the surrounding drop-reason definitions.

#[repr(C)]
pub struct SkBuff {
    _private: [u8; 0],
}

#[repr(C)]
pub struct Sock {
    _private: [u8; 0],
}

#[repr(C)]
pub struct SksbDropReason {
    _private: [u8; 0],
}

// enum skb_drop_reason is supplied by linux/skbuff.h.
pub type SkbDropReason = SksbDropReason;

#[repr(C)]
pub struct KfreeSkbEntry {
    pub skbaddr: *mut core::ffi::c_void,
    pub location: *mut core::ffi::c_void,
    pub rx_sk: *const core::ffi::c_void,
    pub protocol: u16,
    pub reason: SkbDropReason,
}

#[repr(C)]
pub struct ConsumeSkbEntry {
    pub skbaddr: *mut core::ffi::c_void,
    pub location: *mut core::ffi::c_void,
}

#[repr(C)]
pub struct SkbCopyDatagramIovecEntry {
    pub skbaddr: *const core::ffi::c_void,
    pub len: core::ffi::c_int,
}

// TRACE_EVENT(kfree_skb): TP_PROTO(struct sk_buff *skb, void *location,
// enum skb_drop_reason reason, const struct sock *rx_sk)
#[inline]
pub unsafe fn kfree_skb_fast_assign(
    entry: *mut KfreeSkbEntry,
    skb: *mut SkBuff,
    location: *mut core::ffi::c_void,
    reason: SkbDropReason,
    rx_sk: *const Sock,
) {
    (*entry).skbaddr = skb.cast();
    (*entry).location = location;
    (*entry).rx_sk = rx_sk.cast();
    (*entry).protocol = u16::from_be((*skb).protocol);
    (*entry).reason = reason;
}

// TRACE_EVENT(consume_skb): TP_PROTO(struct sk_buff *skb, void *location)
#[inline]
pub unsafe fn consume_skb_fast_assign(
    entry: *mut ConsumeSkbEntry,
    skb: *mut SkBuff,
    location: *mut core::ffi::c_void,
) {
    (*entry).skbaddr = skb.cast();
    (*entry).location = location;
}

// TRACE_EVENT(skb_copy_datagram_iovec): TP_PROTO(const struct sk_buff *skb,
// int len)
#[inline]
pub unsafe fn skb_copy_datagram_iovec_fast_assign(
    entry: *mut SkbCopyDatagramIovecEntry,
    skb: *const SkBuff,
    len: core::ffi::c_int,
) {
    (*entry).skbaddr = skb.cast();
    (*entry).len = len;
}

// TP_printk formats retained from the source tracepoints:
// kfree_skb: "skbaddr=%p rx_sk=%p protocol=%u location=%pS reason: %s"
// consume_skb: "skbaddr=%p location=%pS"
// skb_copy_datagram_iovec: "skbaddr=%p len=%d"

